    id: string;
    name: string;
    students: string;
    questions: string;
    timePerQuestion: number; // Thời gian giới hạn cho mỗi câu (giây)
}

export enum GameState {
    IDLE = 'IDLE',
    SPINNING = 'SPINNING',
    ANNOUNCE = 'ANNOUNCE', // New state for winner announcement
    RESULT = 'RESULT', // Used for Question Phase
    CONFIG = 'CONFIG',
    GAME_OVER = 'GAME_OVER'
}

export const QUESTIONS_PER_TURN = 5;
