                        <Trash2 size={20} />
                    </button>

                    <div className="w-px h-6 bg-gray-300 mx-2"></div>

                    {/* Time Limit Setting */}
                    <div className="flex items-center gap-2 px-3 py-1 bg-blue-50 text-blue-700 rounded-lg border border-blue-100">
                        <Clock size={18} />
