                        <input 
                            type="number"
                            min="5"
                            max="300"
                            value={tempTimeLimit}
                            onChange={(e) => handleUpdateCurrentClass('timePerQuestion', parseInt(e.target.value) || 20)}
                            className="w-14 p-1 rounded border-blue-200 text-center font-bold text-blue-800 bg-white"
                        />
