import React, { useState, useMemo } from 'react';
import Wheel from './components/Wheel';
import ConfigPanel from './components/ConfigPanel';
import QuestionModal from './components/QuestionModal';
import HistoryModal from './components/HistoryModal';
import WinnerModal from './components/WinnerModal';
import { Student, Question, GameState, HistoryRecord, DEFAULT_STUDENTS, DEFAULT_QUESTIONS, QUESTIONS_PER_TURN } from './types';
import { Settings, RefreshCw, Trophy, History } from 'lucide-react';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>(GameState.IDLE);
  const [allStudents, setAllStudents] = useState<Student[]>(
    DEFAULT_STUDENTS.map((name, i) => ({ id: `s-${i}`, name, selected: false }))
  );
  const [allQuestions, setAllQuestions] = useState<Question[]>(
    DEFAULT_QUESTIONS.map((text, i) => ({ id: `q-${i}`, text, used: false }))
  );
  const [history, setHistory] = useState<HistoryRecord[]>([]);
  const [showHistory, setShowHistory] = useState(false);

  const [prizeIndex, setPrizeIndex] = useState<number>(0);
  const [mustSpin, setMustSpin] = useState<boolean>(false);
  const [currentWinner, setCurrentWinner] = useState<Student | null>(null);
  const [timeLimit, setTimeLimit] = useState<number>(20); // Default 20s

  const [currentQuestions, setCurrentQuestions] = useState<Question[]>([]);

  const availableStudents = useMemo(() => allStudents.filter(s => !s.selected), [allStudents]);
  const availableQuestions = useMemo(() => allQuestions.filter(q => !q.used), [allQuestions]);

  const handleSpin = () => {
    if (gameState !== GameState.IDLE || availableStudents.length === 0) return;

    const randomIndex = Math.floor(Math.random() * availableStudents.length);
    const winner = availableStudents[randomIndex];

    setPrizeIndex(randomIndex);
    setMustSpin(true);
    setGameState(GameState.SPINNING);
    setCurrentWinner(winner);
  };

  const handleStopSpinning = () => {
    setMustSpin(false);

    if (availableQuestions.length > 0) {
        const shuffled = [...availableQuestions].sort(() => 0.5 - Math.random());
        const selected = shuffled.slice(0, Math.min(QUESTIONS_PER_TURN, shuffled.length));

        if (selected.length < QUESTIONS_PER_TURN) {
            alert(`Cảnh báo: Chỉ còn ${selected.length} câu hỏi khả dụng.`);
        }

        setCurrentQuestions(selected);
        setGameState(GameState.ANNOUNCE);
    } else {
        alert("Hết câu hỏi! Vui lòng thêm câu hỏi mới trong cấu hình hoặc reset.");
        setCurrentQuestions([]);
        setGameState(GameState.IDLE); 
    }
  };

  const handleStartQuiz = () => {
    setGameState(GameState.RESULT);
  };

  const handleModalResult = (score: number) => {
    if (currentWinner) {
        const newRecord: HistoryRecord = {
            id: Date.now().toString(),
            studentName: currentWinner.name,
            score: score,
            totalQuestions: currentQuestions.length,
            timestamp: Date.now()
        };
        setHistory(prev => [newRecord, ...prev]);
    }

    if (currentWinner) {
        setAllStudents(prev => prev.map(s => s.id === currentWinner.id ? { ...s, selected: true } : s));
    }

    const usedIds = new Set(currentQuestions.map(q => q.id));
    setAllQuestions(prev => prev.map(q => usedIds.has(q.id) ? { ...q, used: true } : q));

    setGameState(GameState.IDLE);
    setCurrentWinner(null);
    setCurrentQuestions([]);
  };

  const handleSaveConfig = (studentsStr: string, questionsStr: string, newTimeLimit: number) => {
    const sList = studentsStr.split('\n').map(s => s.trim()).filter(s => s);
    const qList = questionsStr.split(/\n\s*\n/).map(q => q.trim()).filter(q => q);

    setAllStudents(sList.map((name, i) => ({ id: `s-${Date.now()}-${i}`, name, selected: false })));
    setAllQuestions(qList.map((text, i) => ({ id: `q-${Date.now()}-${i}`, text, used: false })));
    setTimeLimit(newTimeLimit);

    setGameState(GameState.IDLE);
  };

  const handleReset = () => {
    if (window.confirm("Bạn có chắc muốn đặt lại trạng thái (tất cả học sinh và câu hỏi sẽ được reset)?")) {
        setAllStudents(prev => prev.map(s => ({ ...s, selected: false })));
        setAllQuestions(prev => prev.map(q => ({ ...q, used: false })));
    }
  };

  if (gameState === GameState.CONFIG) {
    const rawStudents = allStudents.map(s => s.name).join('\n');
    const rawQuestions = allQuestions.map(q => q.text).join('\n\n');
    return (
        <div className="min-h-screen bg-blue-50 p-8 flex items-center justify-center">
            <ConfigPanel 
                rawStudents={rawStudents} 
                rawQuestions={rawQuestions} 
                initialTimeLimit={timeLimit}
                onSave={handleSaveConfig} 
                onCancel={() => setGameState(GameState.IDLE)} 
            />
        </div>
    );
  }

  return (
    <div className="min-h-screen bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] bg-blue-50 text-gray-800 flex flex-col overflow-hidden font-sans">

      <header className="p-4 flex justify-between items-center bg-white shadow-sm z-10 shrink-0">
        <div className="flex items-center gap-2">
            <div className="w-10 h-10 bg-gradient-to-br from-yellow-400 to-orange-500 rounded-full flex items-center justify-center text-white font-bold text-xl shadow-md">
                <Trophy size={20} />
            </div>
            <h1 className="text-2xl font-bold text-blue-900 tracking-tight hidden sm:block">Vòng Quay Tri Thức</h1>
        </div>
        <div className="flex gap-2">
            <button 
                onClick={() => setShowHistory(true)}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded-full font-bold transition-colors"
            >
                <History size={18} />
                <span className="hidden sm:inline">Lịch sử</span>
            </button>
            <div className="w-px h-8 bg-gray-300 mx-1"></div>
            <button 
                onClick={handleReset}
                className="p-2 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded-full transition-colors"
                title="Reset danh sách"
            >
                <RefreshCw size={24} />
            </button>
            <button 
                onClick={() => setGameState(GameState.CONFIG)}
                className="flex items-center gap-2 px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded-full text-gray-700 font-bold transition-colors"
            >
                <Settings size={18} />
                <span className="hidden sm:inline">Cấu hình</span>
            </button>
        </div>
      </header>

      <main className="flex-grow flex flex-col items-center justify-center p-4 relative w-full">

        {availableStudents.length === 0 ? (
            <div className="text-center p-12 bg-white rounded-3xl shadow-xl border-4 border-dashed border-gray-300 animate-fade-in z-20">
                <p className="text-2xl text-gray-500 mb-4">Đã quay hết danh sách học sinh!</p>
                <div className="flex justify-center gap-4">
                    <button 
                        onClick={() => setShowHistory(true)}
                        className="px-6 py-3 bg-indigo-500 text-white rounded-full font-bold hover:bg-indigo-600"
                    >
                        Xem kết quả
                    </button>
                    <button 
                        onClick={handleReset}
                        className="px-6 py-3 bg-blue-500 text-white rounded-full font-bold hover:bg-blue-600"
                    >
                        Làm mới danh sách
                    </button>
                </div>
            </div>
        ) : (
            <div className="w-full max-w-[90vw] flex flex-col md:flex-row items-center justify-center gap-8 md:gap-20 z-10 relative md:pl-40">
                <div className="flex-1 w-full flex justify-center md:justify-end">
                    <Wheel 
                        students={availableStudents}
                        mustSpin={mustSpin}
                        prizeNumber={prizeIndex}
                        onStopSpinning={handleStopSpinning}
                    />
                </div>

                <div className="flex-1 w-full flex flex-col items-center md:items-start justify-center gap-6">
                    <button
                        onClick={handleSpin}
                        disabled={mustSpin}
                        className={`
                            px-12 py-8 rounded-full text-2xl md:text-3xl font-black text-white shadow-[0_10px_0_rgb(0,0,0,0.2)] 
                            active:shadow-none active:translate-y-[10px] transition-all transform hover:scale-105
                            uppercase tracking-wider min-w-[250px]
                            ${mustSpin 
                                ? 'bg-gray-400 cursor-not-allowed shadow-none translate-y-[10px]' 
                                : 'bg-gradient-to-b from-red-500 to-red-600 hover:from-red-400 hover:to-red-500'}
                        `}
                    >
                        {mustSpin ? 'Đang quay...' : 'QUAY NGAY!'}
                    </button>
                    <div className="text-gray-500 text-sm font-bold italic opacity-70 bg-white/50 px-10 py-1 rounded-full backdrop-blur-sm shadow-sm">
                        Được chia sẻ bởi TRANVINHSD
                    </div>
                </div>
            </div>
        )}

        <div className="absolute top-4 left-4 bg-white/80 backdrop-blur p-4 rounded-xl shadow-sm text-lg border border-white z-20">
            <p>Học sinh còn lại: <strong>{availableStudents.length}</strong></p>
            <p>Câu hỏi còn lại: <strong>{availableQuestions.length}</strong></p>
            <p className="mt-2 text-blue-600 font-bold">Thời gian/câu: {timeLimit}s</p>
        </div>

      </main>

      {gameState === GameState.ANNOUNCE && currentWinner && (
        <WinnerModal 
            studentName={currentWinner.name}
            onStart={handleStartQuiz}
        />
      )}

      {gameState === GameState.RESULT && currentWinner && currentQuestions.length > 0 && (
        <QuestionModal 
            studentName={currentWinner.name}
            questions={currentQuestions}
            timeLimit={timeLimit}
            onFinish={handleModalResult}
        />
      )}

      {showHistory && (
        <HistoryModal 
            history={history} 
            onClose={() => setShowHistory(false)} 
        />
      )}

    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { soundFX } from '../utils/sound';
import { Check, X, ArrowRight, Trophy, Clock } from 'lucide-react';
import { Question, POINTS_PER_QUESTION, QUESTIONS_PER_TURN } from '../types';

interface QuestionModalProps {
    studentName: string;
    questions: Question[];
    timeLimit: number;
    onFinish: (score: number) => void;
}

const QuestionModal: React.FC<QuestionModalProps> = ({ studentName, questions, timeLimit, onFinish }) => {
    const [currentIndex, setCurrentIndex] = useState(0);
    const [score, setScore] = useState(0);
    const [selectedOption, setSelectedOption] = useState<string | null>(null);
    const [isChecked, setIsChecked] = useState(false);
    const [isQuizFinished, setIsQuizFinished] = useState(false);

    // Timer state
    const [timeLeft, setTimeLeft] = useState(timeLimit);
    const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

    // Get current question string
    const currentQuestionText = questions[currentIndex]?.text || "";

    // Parse the current question text
    const { mainQuestion, options, correctLetter } = useMemo(() => {
        const lines = currentQuestionText.split('\n').map(l => l.trim()).filter(l => l);

        // Find answer line
        const answerIndex = lines.findIndex(l => l.toLowerCase().startsWith('đáp án') || l.toLowerCase().startsWith('answer'));

        let correctLetter = "";
        let contentLines = lines;

        if (answerIndex !== -1) {
            const answerLine = lines[answerIndex];
            const match = answerLine.match(/:\s*([A-D])/i);
            if (match && match[1]) {
                correctLetter = match[1].toUpperCase();
            }
            contentLines = lines.filter((_, i) => i !== answerIndex);
        }

        let mainQuestion = "";
        let options: string[] = [];

        if (contentLines.length > 1) {
            mainQuestion = contentLines[0];
            options = contentLines.slice(1);
        } else {
            mainQuestion = contentLines[0] || "";
        }

        return { mainQuestion, options, correctLetter };
    }, [currentQuestionText]);

    // Timer logic
    useEffect(() => {
        if (!isChecked && !isQuizFinished) {
            setTimeLeft(timeLimit);
            timerRef.current = setInterval(() => {
                setTimeLeft(prev => {
                    if (prev <= 1) {
                        clearInterval(timerRef.current!);
                        handleCheck(true); // Auto-check when time runs out
                        return 0;
                    }
                    return prev - 1;
                });
            }, 1000);
        }

        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, [currentIndex, isChecked, isQuizFinished, timeLimit]);

    const handleOptionClick = (optText: string) => {
        if (isChecked) return;

        const match = optText.match(/^([A-D])\./i);
        if (match && match[1]) {
            setSelectedOption(match[1].toUpperCase());
        } else {
            setSelectedOption(optText); 
        }
    };

    const handleCheck = (isAuto = false) => {
        if (isChecked) return;
        if (timerRef.current) clearInterval(timerRef.current);

        const isCorrect = selectedOption === correctLetter;

        if (isCorrect) {
            soundFX.playCorrectSound();
            setScore(prev => prev + POINTS_PER_QUESTION);
        } else {
            soundFX.playWrongSound();
        }

        setIsChecked(true);
    };

    const handleNext = () => {
        if (currentIndex < questions.length - 1) {
            setCurrentIndex(prev => prev + 1);
            setSelectedOption(null);
            setIsChecked(false);
        } else {
            soundFX.playWinSound();
            setIsQuizFinished(true);
        }
    };

    const handleClose = () => {
        onFinish(score);
    };

    const getOptionStyle = (optText: string) => {
        const match = optText.match(/^([A-D])\./i);
        const optLetter = match ? match[1].toUpperCase() : "";

        let baseStyle = "p-4 border-2 rounded-xl text-3xl font-medium cursor-pointer transition-all shadow-sm leading-normal ";

        if (isChecked) {
            if (optLetter === correctLetter) {
                return baseStyle + "bg-green-100 border-green-500 text-green-800 shadow-md ring-4 ring-green-200";
            }
            if (selectedOption === optLetter && optLetter !== correctLetter) {
                return baseStyle + "bg-red-100 border-red-500 text-red-800 opacity-80";
            }
            return baseStyle + "bg-gray-50 border-gray-200 text-gray-400 opacity-50";
        } else {
            if (selectedOption === optLetter) {
                return baseStyle + "bg-blue-100 border-blue-500 text-blue-900 shadow-md transform scale-[1.01]";
            }
            return baseStyle + "bg-white border-blue-100 hover:border-blue-300 hover:bg-blue-50 text-gray-800";
        }
    };

    const progressPercentage = (timeLeft / timeLimit) * 100;

    if (isQuizFinished) {
        return (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
                <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl overflow-hidden animate-bounce-in border-4 border-yellow-500 p-8 text-center">
                    <div className="mb-6 flex justify-center">
                        <div className="w-24 h-24 bg-yellow-100 rounded-full flex items-center justify-center text-yellow-600">
                            <Trophy size={48} />
                        </div>
                    </div>
                    <h2 className="text-3xl font-extrabold text-gray-800 mb-2">Hoàn thành xuất sắc!</h2>
                    <p className="text-gray-500 text-lg mb-8">Học sinh: <span className="font-bold text-blue-600">{studentName}</span></p>

                    <div className="bg-gradient-to-r from-blue-500 to-indigo-600 text-white p-6 rounded-2xl mb-8 shadow-lg">
                        <p className="text-sm uppercase font-bold opacity-80 mb-1">Tổng điểm</p>
                        <p className="text-6xl font-black">{score} <span className="text-3xl font-normal">/ {questions.length * POINTS_PER_QUESTION}</span></p>
                    </div>

                    <button 
                        onClick={handleClose}
                        className="w-full py-4 bg-green-500 text-white rounded-xl font-bold text-3xl hover:bg-green-600 transition-colors shadow-lg"
                    >
                        Lưu kết quả & Đóng
                    </button>
                </div>
            </div>
        );
    }

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
            <div className="bg-white rounded-3xl shadow-3xl w-full max-w-6xl overflow-hidden animate-bounce-in flex flex-col max-h-[95vh]">
                {/* Timer Bar (Top) */}
                {!isChecked && (
                    <div className="w-full h-2 bg-gray-100">
                        <div 
                            className={`h-full transition-all duration-1000 ease-linear ${
                                progressPercentage < 25 ? 'bg-red-500' : progressPercentage < 50 ? 'bg-yellow-500' : 'bg-green-500'
                            }`}
                            style={{ width: `${progressPercentage}%` }}
                        ></div>
                    </div>
                )}

                {/* Header */}
                <div className="bg-blue-600 p-4 text-white flex justify-between items-center shrink-0">
                    <div className="flex items-center gap-4">
                        <div className="bg-white/20 px-4 py-2 rounded-lg font-bold">
                            Câu {currentIndex + 1} / {questions.length}
                        </div>
                        <div className="text-3xl font-semibold opacity-90">
                            Người may mắn: {studentName}
                        </div>
                    </div>

                    <div className="flex items-center gap-4">
                        {!isChecked && (
                            <div className={`flex items-center gap-2 px-4 py-2 rounded-lg font-mono text-2xl font-black shadow-inner ${
                                timeLeft <= 5 ? 'bg-red-100 text-red-600 animate-pulse' : 'bg-white/20 text-white'
                            }`}>
                                <Clock size={24} />
                                {timeLeft}s
                            </div>
                        )}
                        <div className="bg-yellow-400 text-yellow-900 px-4 py-2 rounded-lg font-bold shadow-sm">
                            Điểm: {score}
                        </div>
                    </div>
                </div>

                {/* Content */}
                <div className="p-8 overflow-y-auto flex-grow bg-gray-50">
                    <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-200 mb-6">
                        <p className="text-3xl md:text-3xl font-bold text-gray-800 leading-relaxed">{mainQuestion}</p>
                    </div>

                    {/* Options Grid */}
                    <div className="grid grid-cols-1 gap-4">
                        {options.map((opt, idx) => (
                            <div 
                                key={idx} 
                                onClick={() => handleOptionClick(opt)}
                                className={getOptionStyle(opt)}
                            >
                                {opt}
                            </div>
                        ))}
                    </div>

                    {isChecked && selectedOption === null && timeLeft === 0 && (
                        <div className="mt-6 p-4 bg-red-50 border border-red-200 rounded-2xl text-red-700 text-center font-bold text-xl">
                            Hết thời gian! Bạn đã bỏ lỡ câu hỏi này.
                        </div>
                    )}
                </div>

                {/* Footer Controls */}
                <div className="p-6 bg-white border-t border-gray-200 shrink-0 flex justify-end gap-4">
                    {!isChecked ? (
                        <button 
                            onClick={() => handleCheck()}
                            disabled={!selectedOption}
                            className={`flex items-center gap-2 px-8 py-4 rounded-xl font-bold text-2xl transition-all ${
                                selectedOption 
                                ? 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg' 
                                : 'bg-gray-200 text-gray-400 cursor-not-allowed'
                            }`}
                        >
                            <Check className="w-6 h-6" />
                            Kiểm tra
                        </button>
                    ) : (
                        <button 
                            onClick={handleNext}
                            className="flex items-center gap-2 px-8 py-4 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-colors font-bold text-xl shadow-lg animate-pulse-soft"
                        >
                            {currentIndex < questions.length - 1 ? "Câu tiếp theo" : "Xem kết quả"}
                            <ArrowRight className="w-6 h-6" />
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
};

