import { GoogleGenAI } from "@google/genai";

export const generateQuestions = async (topic: string, count: number = 5): Promise<string[]> => {
    if (!process.env.API_KEY) {
        console.warn("API Key is missing for Gemini");
        return [];
    }

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Tạo danh sách gồm ĐÚNG ${count} câu hỏi trắc nghiệm về chủ đề "${topic}" dành cho học sinh.
        Định dạng BẮT BUỘC cho mỗi câu hỏi như sau (không dùng định dạng Markdown, không in đậm):

        [Nội dung câu hỏi]
        A. [Lựa chọn 1]
        B. [Lựa chọn 2]
        C. [Lựa chọn 3]
        D. [Lựa chọn 4]
        Đáp án: [Đáp án đúng]

        Mỗi câu hỏi cách nhau bởi một dòng trống. Không thêm lời dẫn, chỉ xuất danh sách câu hỏi. Đảm bảo số lượng câu hỏi là chính xác ${count} câu.`;

        // Use gemini-3-flash-preview as recommended for Basic Text Tasks
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
        });

        const text = response.text || "";
        // Split by double newline to get individual question blocks
        return text.split(/\n\s*\n/).map(q => q.trim()).filter(q => q.length > 0);
    } catch (error) {
        console.error("Error generating questions:", error);
        return [];
    }
};

